static class RebirthWorldCharacterRepository{public static bool IsServerAuthority=true,FailSolo;public static bool IsCurrentCachedRecord(RebirthWorldCharacterRecord r)=>r!=null;public static bool SaveIfDirty(RebirthStablePlayerIdentity i,string why){if(why=="solo-theory-original-teaching"&&FailSolo)return false;i.Record.Dirty=false;if(i.Record.Progression.SoloTheory!=null)i.Record.Saved=i.Record.Progression.SoloTheory.Clone();return true;}public static bool HasSavedSoloTeachingOriginal(RebirthStablePlayerIdentity i,RebirthTheorySoloState s)=>i.Record.Saved!=null&&XNode.DeepEquals(i.Record.Saved.TeachingOriginal.Write(),s.TeachingOriginal.Write())&&i.Record.Saved.Evidence.Count==s.Evidence.Count;}
static class RebirthSkillAwardService{public static Dictionary<int,RebirthStablePlayerIdentity> Owners=new Dictionary<int,RebirthStablePlayerIdentity>();public static int Awards;public static bool TryGetEligible(EntityPlayer p,out RebirthStablePlayerIdentity i,out RebirthWorldCharacterRecord r){bool found=Owners.TryGetValue(p.entityId,out i);r=i?.Record;return found;}public static bool TryAwardMigratedTrainingEvidence(EntityPlayer p,RebirthSkillTrainingEvidence e,out RebirthSkillTrainingComputation c,out float s,out float a){Awards++;c=null;s=a=0;Owners[p.entityId].Record.Progression.SkillAwardReceipts.Add(e.DurableReceiptId);return true;}}
