static class RebirthAtomicXmlFile{public static int Fault;public static bool TryWrite(string path,XDocument doc,out string error){error="fault";Directory.CreateDirectory(Path.GetDirectoryName(path));if(Fault==1)return false;doc.Save(path);return Fault!=2;}public static bool TryLoadFinalThenBackup(string path,out XDocument doc,out bool backup,out string error){doc=null;backup=false;error="";try{doc=XDocument.Load(path);return true;}catch{return false;}}}
