class Check{
 static readonly object Gate=new object();static readonly HashSet<int> LessonPlayers=new HashSet<int>(),DirtyLessonPlayers=new HashSet<int>();static readonly Dictionary<int,float> NextLessonRevisionPublish=new Dictionary<int,float>();static void PublishSavedOutcome(EntityPlayer p,string reason){}static void AddBoundedReceipt(HashSet<string> r,string receipt,string protectedReceipt=null){r.Add(receipt);}static void PruneHistory(ProgressionState p){}
 // SOURCE
 static int count;static void Assert(bool x,string why){if(!x)throw new Exception(count+" "+why);count++;}
 static void Main(string[] args){GameIO.Directory=args[0];var w=new World();GameManager.Instance.World=w;var teacher=new EntityPlayer{entityId=1,world=w};var student=new EntityPlayer{entityId=2,world=w};w.Players[1]=teacher;w.Players[2]=student;var ir=new RebirthWorldCharacterRecord();var sr=new RebirthWorldCharacterRecord();ir.Origin.CreationId=new string('a',32);sr.Origin.CreationId=new string('b',32);sr.Progression.SkillKnowledge["skill.cooking"]=new RebirthSkillKnowledgeRuntimeState();var ii=new RebirthStablePlayerIdentity{StorageKey="teacher",Record=ir};var si=new RebirthStablePlayerIdentity{StorageKey="student",Record=sr};RebirthSkillAwardService.Owners[1]=ii;RebirthSkillAwardService.Owners[2]=si;var o=new RebirthTeachingDurableOutcome{OutcomeId="original",InstructorStorageKey=ii.StorageKey,StudentStorageKey=si.StorageKey,InstructorCreationId=ir.Origin.CreationId,StudentCreationId=sr.Origin.CreationId,SkillId="skill.cooking",HistoryKey="history",HistoryTargetCount=1,CompletedUtcTicks=1,StudentKnowledgeTarget=42,TeacherAward=.4f};string error;
 Assert(RebirthTeachingOutcomeStore.TryReserveOriginal(o,0,out error),"reserve original");Assert(ir.Progression.SoloTheory==null,"admission no evidence");RebirthWorldCharacterRepository.FailSolo=true;Assert(!TryApplyDurableOutcome(o,teacher,student,ii,ir,si,sr),"Solo unknown save holds after actual participant stages");Assert(o.StudentApplied&&o.InstructorApplied&&!o.SoloEvidenceApplied&&!o.RewardApplied,"ordered stages");Assert(sr.Progression.SkillKnowledge["skill.cooking"].Value==42&&ir.Progression.TeachingHistory["history"].CompletionCount==1,"actual participant transfer/history");Assert(ir.Progression.SoloTheory.Evidence.Count==1&&RebirthSkillAwardService.Awards==0,"prepared Solo evidence not reward completion");Assert(!TryApplyDurableOutcome(o,teacher,student,ii,ir,si,sr)&&ir.Progression.SoloTheory.Evidence.Count==1,"same retry no duplicate");RebirthWorldCharacterRepository.FailSolo=false;Assert(TryApplyDurableOutcome(o,teacher,student,ii,ir,si,sr),"exact original continuation");Assert(o.SoloEvidenceApplied&&o.RewardApplied&&ir.Saved.Evidence.Count==1&&RebirthSkillAwardService.Awards==1,"saved Solo then original reward");Assert(RebirthTeachingOutcomeStore.Snapshot().Length==0,"all four retire original");Assert(!TryApplyDurableOutcome(o,teacher,student,ii,ir,si,sr)&&RebirthSkillAwardService.Awards==1,"retired callback rejected before mutation");var legacy=new RebirthTeachingDurableOutcome{OutcomeId="legacy",InstructorStorageKey=ii.StorageKey,StudentStorageKey=si.StorageKey,InstructorCreationId=ir.Origin.CreationId,StudentCreationId=sr.Origin.CreationId,SkillId="skill.cooking",HistoryKey="legacy",HistoryTargetCount=1,CompletedUtcTicks=2,StudentKnowledgeTarget=43,TeacherAward=.4f};Assert(RebirthTeachingOutcomeStore.TryReserve(legacy,out error)&&TryApplyDurableOutcome(legacy,teacher,student,ii,ir,si,sr)&&ir.Saved.Evidence.Count==1,"legacy stages preserve behavior without retroactive Solo");Console.WriteLine(count+" PASS actual Teaching orchestration + original journal + Solo evidence producer");}
